import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './index.js';
import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });

  it('exports ListSessionsMessage, SessionSummaryFrame and SessionListMessage in the frame unions', () => {
    const listRequest: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
    };
    const summaryFrame: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:01:00.000Z',
      entryCount: 2,
    };
    const listResponse: SessionListMessage = {type: 'session_list', sessions: [summaryFrame]};
    const incomingFrame: IncomingMessage = listRequest;
    const outgoingFrame: OutgoingMessage = listResponse;

    expect({incomingFrame, outgoingFrame}).toEqual({incomingFrame: listRequest, outgoingFrame: listResponse});
  });
});

