import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });
});

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('validates list_sessions with optional limit and before, stripping extra fields', () => {
    const bare = validateMessage({type: 'list_sessions'});
    const paged = validateMessage({
      type: 'list_sessions',
      limit: 0,
      before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3', extra: 'drop'},
      userId: 'u2',
    });
    const epochCursor = validateMessage({
      type: 'list_sessions',
      limit: 20,
      before: {updatedAt: 1767225900000, sessionId: 's4'},
    });
    const malformedPayloads = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', limit: Number.POSITIVE_INFINITY},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: null},
      {type: 'list_sessions', before: []},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: Number.NaN, sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    expect({
      bare,
      paged,
      epochCursor,
      rejected: malformedPayloads.map(payload => validateMessage(payload).valid),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      paged: {
        valid: true,
        data: {type: 'list_sessions', limit: 0, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'}},
      },
      epochCursor: {
        valid: true,
        data: {type: 'list_sessions', limit: 20, before: {updatedAt: 1767225900000, sessionId: 's4'}},
      },
      rejected: Array(malformedPayloads.length).fill(false),
    });
  });
});

